function clamp(val, min_val, max_val):
    if val < min_val:
        return min_val
    if val > max_val:
        return max_val
    return val

function pseudo_random():
    // 64-bit linear congruential generator using Table 2 RNG seed
    global rng_seed
    rng_seed = (rng_seed * 6364136223846793005 + 1) & 0xFFFFFFFFFFFFFFFF
    return (rng_seed >> 32) & 0xFFFFFFFF

function update(PC, actual_taken, sc_needs_update, sc_correct, base_correct):
    if not sc_needs_update:
        return

    min_weight = -(1 << (weight_width_bits - 1))
    max_weight = (1 << (weight_width_bits - 1)) - 1

    for b = 0 to 7:
        avail = branch_context.sR_available_regs[b]
        if len(avail) == 0:
            continue

        // Paper Section 4.2: If multiple registers were available, randomly select one for single-port update
        reg_to_update = avail[pseudo_random() % len(avail)]
        digest = sR_RegStatus[reg_to_update].payload & 0x0FFF

        w_idx0 = hash0(PC, digest) % 512
        w_idx1 = hash1(PC, digest) % 256
        w_idx2 = hash2(PC, digest) % 128

        // 1. Update WT saturating counter entries: +1 if taken, -1 if not taken
        step = actual_taken ? +1 : -1
        sR_WT[b].WT0[w_idx0] = clamp(sR_WT[b].WT0[w_idx0] + step, min_weight, max_weight)
        sR_WT[b].WT1[w_idx1] = clamp(sR_WT[b].WT1[w_idx1] + step, min_weight, max_weight)
        sR_WT[b].WT2[w_idx2] = clamp(sR_WT[b].WT2[w_idx2] + step, min_weight, max_weight)

        // 2. Update UT usefulness tables
        u_idx0 = hash_u0(PC) % 8
        u_idx1 = hash_u1(PC) % 8
        u_idx2 = hash_u2(PC) % 8

        reg_slot = reg_to_update >> 3

        bank_pred_taken = (branch_context.sR_bank_sum[b] >= 0)
        u_step = 0
        if bank_pred_taken == actual_taken and bank_pred_taken != base_correct:
            u_step = +1
        elif bank_pred_taken != actual_taken:
            u_step = -1

        if u_step != 0:
            sR_UT[b].UT0[u_idx0][reg_slot] = clamp(sR_UT[b].UT0[u_idx0][reg_slot] + u_step, min_weight, max_weight)
            sR_UT[b].UT1[u_idx1][reg_slot] = clamp(sR_UT[b].UT1[u_idx1][reg_slot] + u_step, min_weight, max_weight)
            sR_UT[b].UT2[u_idx2][reg_slot] = clamp(sR_UT[b].UT2[u_idx2][reg_slot] + u_step, min_weight, max_weight)
